     1→/**
     2→ * FreeWire Phase 5 - AI 노드 자동 생성기
     3→ *
     4→ * 텍스트 한 줄 → 노드 그래프 JSON 자동 생성
     5→ *
     6→ * 동작 방식:
     7→ *   1. IntentParser: 자연어 → 의도 파악 (키워드 + 패턴)
     8→ *   2. TemplateEngine: 의도 → 노드 배치 계획
     9→ *   3. LayoutEngine: 노드 위치 자동 계산 (겹침 방지)
    10→ *   4. (선택) LLM 브릿지: 로컬 서버 or Claude API 연동
    11→ */
    12→
    13→'use strict';
    14→
    15→// ─── 노드 팩토리 ─────────────────────────────────────────────────
    16→
    17→let _idCtr = 1;
    18→const uid = () => `ai-${_idCtr++}`;
    19→
    20→const NODE = {
    21→  button: (label = '버튼', variant = 'primary') => ({
    22→    id: uid(), type: 'component', subtype: 'button', label: `버튼[${label}]`,
    23→    inputs: [{ name: 'props', portType: 'data' }, { name: 'onClick', portType: 'logic' }],
    24→    outputs: [{ name: 'element', portType: 'component' }],
    25→    props: { label, variant },
    26→  }),
    27→
    28→  text: (content = '텍스트', tag = 'p') => ({
    29→    id: uid(), type: 'component', subtype: 'text', label: `텍스트[${content.slice(0,8)}]`,
    30→    inputs: [{ name: 'content', portType: 'data' }],
    31→    outputs: [{ name: 'element', portType: 'component' }],
    32→    props: { content, tag },
    33→  }),
    34→
    35→  input: (placeholder = '입력', type = 'text') => ({
    36→    id: uid(), type: 'component', subtype: 'input', label: `입력[${placeholder}]`,
    37→    inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
    38→    outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
    39→    props: { placeholder, type },
    40→  }),
    41→
    42→  card: (title = '카드') => ({
    43→    id: uid(), type: 'component', subtype: 'card', label: `카드[${title}]`,
    44→    inputs: [{ name: 'title', portType: 'data' }, { name: 'children', portType: 'component' }],
    45→    outputs: [{ name: 'element', portType: 'component' }],
    46→    props: { title },
    47→  }),
    48→
    49→  container: (direction = 'column') => ({
    50→    id: uid(), type: 'component', subtype: 'container', label: `컨테이너`,
    51→    inputs: [{ name: 'children', portType: 'component' }],
    52→    outputs: [{ name: 'element', portType: 'component' }],
    53→    props: { direction, gap: '12px' },
    54→  }),
    55→
    56→  state: (name = 'value', initial = '0') => ({
    57→    id: uid(), type: 'data', subtype: 'state', label: `상태[${name}]`,
    58→    inputs: [{ name: 'set', portType: 'data' }],
    59→    outputs: [{ name: 'value', portType: 'data' }],
    60→    props: { name, initial },
    61→  }),
    62→
    63→  constant: (value = '', valueType = 'string') => ({
    64→    id: uid(), type: 'data', subtype: 'const', label: `상수`,
    65→    inputs: [],
    66→    outputs: [{ name: 'value', portType: 'data' }],
    67→    props: { value, valueType },
    68→  }),
    69→
    70→  array: (items = '[]') => ({
    71→    id: uid(), type: 'data', subtype: 'array', label: `배열`,
    72→    inputs: [],
    73→    outputs: [{ name: 'items', portType: 'data' }],
    74→    props: { items },
    75→  }),
    76→
    77→  handler: (name = 'handleClick') => ({
    78→    id: uid(), type: 'logic', subtype: 'handler', label: `핸들러[${name}]`,
    79→    inputs: [{ name: 'action', portType: 'logic' }],
    80→    outputs: [{ name: 'handler', portType: 'logic' }],
    81→    props: { name },
    82→  }),
    83→
    84→  setState: (target = 'value') => ({
    85→    id: uid(), type: 'logic', subtype: 'setState', label: `setState[${target}]`,
    86→    inputs: [{ name: 'trigger', portType: 'event' }, { name: 'value', portType: 'data' }],
    87→    outputs: [{ name: 'done', portType: 'event' }],
    88→    props: { target },
    89→  }),
    90→
    91→  condition: (operator = '==', value = 'true') => ({
    92→    id: uid(), type: 'logic', subtype: 'condition', label: `조건`,
    93→    inputs: [{ name: 'condition', portType: 'data' }],
    94→    outputs: [{ name: 'true', portType: 'logic' }, { name: 'false', portType: 'logic' }],
    95→    props: { operator, value },
    96→  }),
    97→};
    98→
    99→// ─── 의도 파서 ────────────────────────────────────────────────────
   100→
   101→class IntentParser {
   102→  parse(text) {
   103→    const t = text.toLowerCase().trim();
   104→
   105→    // 1) 직접 패턴
   106→    for (const [pattern, intent] of PATTERNS) {
   107→      if (pattern.test(t)) return { ...intent, raw: text };
   108→    }
   109→
   110→    // 2) 키워드 추출로 복합 의도
   111→    const keywords = this._extractKeywords(t);
   112→    return this._buildFromKeywords(keywords, text);
   113→  }
   114→
   115→  _extractKeywords(t) {
   116→    const kw = { components: [], data: [], logic: [], style: 'column', title: null };
   117→
   118→    // 제목
   119→    const titleMatch = t.match(/["']([^"']+)["']/) || t.match(/제목[은이]?\s*(.+?)(?:\s+|$)/);
   120→    if (titleMatch) kw.title = titleMatch[1];
   121→
   122→    // 컴포넌트
   123→    if (/(버튼|button|클릭|submit|제출|확인|취소|저장|삭제|추가)/.test(t)) kw.components.push('button');
   124→    if (/(텍스트|text|제목|title|label|표시|출력)/.test(t)) kw.components.push('text');
   125→    if (/(입력|input|필드|field|이메일|email|비밀번호|password|이름|name|검색|search)/.test(t)) kw.components.push('input');
   126→    if (/(카드|card)/.test(t)) kw.components.push('card');
   127→    if (/(리스트|list|목록|항목)/.test(t)) kw.components.push('list');
   128→
   129→    // 데이터
   130→    if (/(상태|state|카운트|count)/.test(t)) kw.data.push('state');
   131→    if (/(배열|array|list|목록|아이템)/.test(t)) kw.data.push('array');
   132→
   133→    // 로직
   134→    if (/(핸들러|클릭|이벤트|handler|event|onClick)/.test(t)) kw.logic.push('handler');
   135→    if (/(조건|if|else|분기)/.test(t)) kw.logic.push('condition');
   136→
   137→    // 레이아웃
   138→    if (/(가로|row|수평|horizontal)/.test(t)) kw.style = 'row';
   139→
   140→    return kw;
   141→  }
   142→
   143→  _buildFromKeywords(kw, raw) {
   144→    // 컴포넌트가 없으면 일반 텍스트로
   145→    if (kw.components.length === 0 && kw.data.length === 0) {
   146→      return { type: 'generic', label: raw, raw };
   147→    }
   148→    return { type: 'custom', keywords: kw, raw };
   149→  }
   150→}
   151→
   152→// 고정 패턴
   153→const PATTERNS = [
   154→  [/로그인|login|sign.?in/, { type: 'login' }],
   155→  [/회원가입|register|sign.?up/, { type: 'register' }],
   156→  [/카운터|counter|숫자\s*세기/, { type: 'counter' }],
   157→  [/검색|search/, { type: 'search' }],
   158→  [/(할일|todo|task)\s*(리스트|list|목록)?/, { type: 'todo' }],
   159→  [/(프로필|profile)\s*(카드|card)?/, { type: 'profile-card' }],
   160→  [/(댓글|comment)\s*(폼|form)?/, { type: 'comment-form' }],
   161→  [/(결제|payment|checkout)\s*(폼|form)?/, { type: 'checkout' }],
   162→  [/(설정|setting|config)\s*(폼|form|페이지)?/, { type: 'settings' }],
   163→  [/(대시보드|dashboard)/, { type: 'dashboard' }],
   164→  [/(모달|modal|팝업|popup)/, { type: 'modal' }],
   165→  [/네비게이션|navbar|nav\s*bar/, { type: 'navbar' }],
   166→  [/버튼/, { type: 'single-button' }],
   167→  [/카드/, { type: 'single-card' }],
   168→  [/(입력|input)\s*(폼|form)/, { type: 'input-form' }],
   169→];
   170→
   171→// ─── 템플릿 엔진 ──────────────────────────────────────────────────
   172→
   173→class TemplateEngine {
   174→  generate(intent) {
   175→    const gen = TEMPLATES[intent.type];
   176→    if (gen) return gen(intent);
   177→
   178→    // 커스텀 키워드 기반
   179→    if (intent.type === 'custom') return this._generateCustom(intent);
   180→
   181→    // 폴백: 단순 텍스트 + 버튼
   182→    return this._generateFallback(intent.raw);
   183→  }
   184→
   185→  _generateCustom(intent) {
   186→    const { keywords } = intent;
   187→    const nodes = [], edges = [];
   188→    let hasContainer = keywords.components.length > 1;
   189→    let container = null;
   190→
   191→    if (hasContainer) {
   192→      container = NODE.container(keywords.style);
   193→      nodes.push(container);
   194→    }
   195→
   196→    // 데이터 먼저
   197→    let stateNode = null;
   198→    if (keywords.data.includes('state')) {
   199→      stateNode = NODE.state('value', '0');
   200→      nodes.push(stateNode);
   201→    }
   202→
   203→    let arrayNode = null;
   204→    if (keywords.data.includes('array')) {
   205→      arrayNode = NODE.array('["항목1","항목2","항목3"]');
   206→      nodes.push(arrayNode);
   207→    }
   208→
   209→    // 컴포넌트
   210→    for (const c of keywords.components) {
   211→      let n;
   212→      if (c === 'button') {
   213→        n = NODE.button('확인');
   214→        nodes.push(n);
   215→        // 핸들러 연결
   216→        if (keywords.logic.includes('handler')) {
   217→          const h = NODE.handler('handleClick');
   218→          nodes.push(h);
   219→          edges.push({ from: h.id, fromPort: 0, to: n.id, toPort: 1 });
   220→        }
   221→      } else if (c === 'text') {
   222→        n = NODE.text(keywords.title ?? '텍스트', 'p');
   223→        nodes.push(n);
   224→        if (stateNode) edges.push({ from: stateNode.id, fromPort: 0, to: n.id, toPort: 0 });
   225→      } else if (c === 'input') {
   226→        n = NODE.input('입력하세요');
   227→        nodes.push(n);
   228→      } else if (c === 'card') {
   229→        n = NODE.card(keywords.title ?? '카드');
   230→        nodes.push(n);
   231→      }
   232→
   233→      if (container && n) {
   234→        edges.push({ from: n.id, fromPort: 0, to: container.id, toPort: 0 });
   235→      }
   236→    }
   237→
   238→    return { nodes, edges, label: intent.raw };
   239→  }
   240→
   241→  _generateFallback(raw) {
   242→    const t = NODE.text(raw.slice(0, 20), 'p');
   243→    const b = NODE.button('확인');
   244→    const c = NODE.container();
   245→    return {
   246→      nodes: [c, t, b],
   247→      edges: [
   248→        { from: t.id, fromPort: 0, to: c.id, toPort: 0 },
   249→        { from: b.id, fromPort: 0, to: c.id, toPort: 0 },
   250→      ],
   251→      label: raw,
   252→    };
   253→  }
   254→}
   255→
   256→// ─── 템플릿 정의 ──────────────────────────────────────────────────
   257→
   258→const TEMPLATES = {
   259→  login: () => {
   260→    const email = NODE.input('이메일', 'email');
   261→    const pw = NODE.input('비밀번호', 'password');
   262→    const btn = NODE.button('로그인', 'primary');
   263→    const handler = NODE.handler('handleLogin');
   264→    const card = NODE.card('로그인');
   265→    return {
   266→      nodes: [card, email, pw, btn, handler],
   267→      edges: [
   268→        { from: email.id, fromPort: 0, to: card.id, toPort: 0 },
   269→        { from: pw.id,    fromPort: 0, to: card.id, toPort: 0 },
   270→        { from: btn.id,   fromPort: 0, to: card.id, toPort: 0 },
   271→        { from: handler.id, fromPort: 0, to: btn.id, toPort: 1 },
   272→      ],
   273→      label: '로그인 폼',
   274→    };
   275→  },
   276→
   277→  register: () => {
   278→    const name = NODE.input('이름', 'text');
   279→    const email = NODE.input('이메일', 'email');
   280→    const pw = NODE.input('비밀번호', 'password');
   281→    const pw2 = NODE.input('비밀번호 확인', 'password');
   282→    const btn = NODE.button('회원가입', 'primary');
   283→    const handler = NODE.handler('handleRegister');
   284→    const card = NODE.card('회원가입');
   285→    return {
   286→      nodes: [card, name, email, pw, pw2, btn, handler],
   287→      edges: [
   288→        { from: name.id,  fromPort: 0, to: card.id, toPort: 0 },
   289→        { from: email.id, fromPort: 0, to: card.id, toPort: 0 },
   290→        { from: pw.id,    fromPort: 0, to: card.id, toPort: 0 },
   291→        { from: pw2.id,   fromPort: 0, to: card.id, toPort: 0 },
   292→        { from: btn.id,   fromPort: 0, to: card.id, toPort: 0 },
   293→        { from: handler.id, fromPort: 0, to: btn.id, toPort: 1 },
   294→      ],
   295→      label: '회원가입 폼',
   296→    };
   297→  },
   298→
   299→  counter: () => {
   300→    const state = NODE.state('count', '0');
   301→    const display = NODE.text('0', 'h2');
   302→    const incBtn = NODE.button('+1', 'primary');
   303→    const decBtn = NODE.button('-1', 'secondary');
   304→    const resetBtn = NODE.button('초기화', 'ghost');
   305→    const incH = NODE.handler('handleInc');
   306→    const decH = NODE.handler('handleDec');
   307→    const container = NODE.container('row');
   308→    return {
   309→      nodes: [state, display, incBtn, decBtn, resetBtn, incH, decH, container],
   310→      edges: [
   311→        { from: state.id,  fromPort: 0, to: display.id, toPort: 0 },
   312→        { from: incH.id,   fromPort: 0, to: incBtn.id, toPort: 1 },
   313→        { from: decH.id,   fromPort: 0, to: decBtn.id, toPort: 1 },
   314→        { from: incBtn.id, fromPort: 0, to: container.id, toPort: 0 },
   315→        { from: decBtn.id, fromPort: 0, to: container.id, toPort: 0 },
   316→        { from: resetBtn.id, fromPort: 0, to: container.id, toPort: 0 },
   317→      ],
   318→      label: '카운터 앱',
   319→    };
   320→  },
   321→
   322→  search: () => {
   323→    const queryState = NODE.state('query', '""');
   324→    const input = NODE.input('검색어 입력...', 'text');
   325→    const btn = NODE.button('검색', 'primary');
   326→    const results = NODE.text('검색 결과', 'p');
   327→    const handler = NODE.handler('handleSearch');
   328→    const container = NODE.container('column');
   329→    const row = NODE.container('row');
   330→    return {
   331→      nodes: [queryState, input, btn, results, handler, container, row],
   332→      edges: [
   333→        { from: queryState.id, fromPort: 0, to: input.id, toPort: 0 },
   334→        { from: handler.id, fromPort: 0, to: btn.id, toPort: 1 },
   335→        { from: input.id,   fromPort: 0, to: row.id, toPort: 0 },
   336→        { from: btn.id,     fromPort: 0, to: row.id, toPort: 0 },
   337→        { from: row.id,     fromPort: 0, to: container.id, toPort: 0 },
   338→        { from: results.id, fromPort: 0, to: container.id, toPort: 0 },
   339→      ],
   340→      label: '검색 UI',
   341→    };
   342→  },
   343→
   344→  todo: () => {
   345→    const items = NODE.state('todos', '[]');
   346→    const input = NODE.input('할 일 입력...', 'text');
   347→    const addBtn = NODE.button('추가', 'primary');
   348→    const list = NODE.text('할 일 목록', 'ul');
   349→    const addH = NODE.handler('handleAdd');
   350→    const container = NODE.container('column');
   351→    const row = NODE.container('row');
   352→    return {
   353→      nodes: [items, input, addBtn, list, addH, container, row],
   354→      edges: [
   355→        { from: items.id,  fromPort: 0, to: list.id, toPort: 0 },
   356→        { from: addH.id,   fromPort: 0, to: addBtn.id, toPort: 1 },
   357→        { from: input.id,  fromPort: 0, to: row.id, toPort: 0 },
   358→        { from: addBtn.id, fromPort: 0, to: row.id, toPort: 0 },
   359→        { from: row.id,    fromPort: 0, to: container.id, toPort: 0 },
   360→        { from: list.id,   fromPort: 0, to: container.id, toPort: 0 },
   361→      ],
   362→      label: 'Todo 리스트',
   363→    };
   364→  },
   365→
   366→  'profile-card': () => {
   367→    const nameConst = NODE.constant('홍길동', 'string');
   368→    const roleConst = NODE.constant('개발자', 'string');
   369→    const nameText = NODE.text('홍길동', 'h3');
   370→    const roleText = NODE.text('개발자', 'p');
   371→    const followBtn = NODE.button('팔로우', 'primary');
   372→    const msgBtn = NODE.button('메시지', 'secondary');
   373→    const card = NODE.card('프로필');
   374→    const btnRow = NODE.container('row');
   375→    return {
   376→      nodes: [nameConst, roleConst, nameText, roleText, followBtn, msgBtn, card, btnRow],
   377→      edges: [
   378→        { from: nameConst.id, fromPort: 0, to: nameText.id, toPort: 0 },
   379→        { from: roleConst.id, fromPort: 0, to: roleText.id, toPort: 0 },
   380→        { from: followBtn.id, fromPort: 0, to: btnRow.id, toPort: 0 },
   381→        { from: msgBtn.id,    fromPort: 0, to: btnRow.id, toPort: 0 },
   382→        { from: nameText.id,  fromPort: 0, to: card.id, toPort: 0 },
   383→        { from: roleText.id,  fromPort: 0, to: card.id, toPort: 0 },
   384→        { from: btnRow.id,    fromPort: 0, to: card.id, toPort: 0 },
   385→      ],
   386→      label: '프로필 카드',
   387→    };
   388→  },
   389→
   390→  'comment-form': () => {
   391→    const authorState = NODE.state('author', '""');
   392→    const commentState = NODE.state('comment', '""');
   393→    const nameInput = NODE.input('작성자 이름', 'text');
   394→    const commentInput = NODE.input('댓글 내용...', 'text');
   395→    const submitBtn = NODE.button('댓글 작성', 'primary');
   396→    const handler = NODE.handler('handleComment');
   397→    const card = NODE.card('댓글 작성');
   398→    return {
   399→      nodes: [authorState, commentState, nameInput, commentInput, submitBtn, handler, card],
   400→      edges: [
   401→        { from: authorState.id,  fromPort: 0, to: nameInput.id, toPort: 0 },
   402→        { from: commentState.id, fromPort: 0, to: commentInput.id, toPort: 0 },
   403→        { from: handler.id,    fromPort: 0, to: submitBtn.id, toPort: 1 },
   404→        { from: nameInput.id,  fromPort: 0, to: card.id, toPort: 0 },
   405→        { from: commentInput.id, fromPort: 0, to: card.id, toPort: 0 },
   406→        { from: submitBtn.id,  fromPort: 0, to: card.id, toPort: 0 },
   407→      ],
   408→      label: '댓글 폼',
   409→    };
   410→  },
   411→
   412→  checkout: () => {
   413→    const nameInput = NODE.input('이름', 'text');
   414→    const cardInput = NODE.input('카드 번호', 'text');
   415→    const expiryInput = NODE.input('유효기간 (MM/YY)', 'text');
   416→    const cvvInput = NODE.input('CVV', 'password');
   417→    const payBtn = NODE.button('결제하기', 'primary');
   418→    const cancelBtn = NODE.button('취소', 'ghost');
   419→    const handler = NODE.handler('handlePay');
   420→    const card = NODE.card('결제 정보');
   421→    const btnRow = NODE.container('row');
   422→    return {
   423→      nodes: [nameInput, cardInput, expiryInput, cvvInput, payBtn, cancelBtn, handler, card, btnRow],
   424→      edges: [
   425→        { from: handler.id,    fromPort: 0, to: payBtn.id, toPort: 1 },
   426→        { from: payBtn.id,     fromPort: 0, to: btnRow.id, toPort: 0 },
   427→        { from: cancelBtn.id,  fromPort: 0, to: btnRow.id, toPort: 0 },
   428→        { from: nameInput.id,  fromPort: 0, to: card.id, toPort: 0 },
   429→        { from: cardInput.id,  fromPort: 0, to: card.id, toPort: 0 },
