   470→    const c1 = NODE.card('총 사용자');
   471→    const c2 = NODE.card('전환율');
   472→    const c3 = NODE.card('매출');
   473→    const refreshBtn = NODE.button('새로고침', 'secondary');
   474→    const container = NODE.container('row');
   475→    return {
   476→      nodes: [stat1, stat2, stat3, c1, c2, c3, refreshBtn, container],
   477→      edges: [
