});

test('offsetX/Y 적용', () => {
  const nodes = [{ id: 'x', type: 'data' }];
  const pos = layoutEng.layout(nodes, [], 200, 150);
  assertEqual(pos['x'].x, 200, 'offsetX');
  assertEqual(pos['x'].y, 150, 'offsetY');
});

test('빈 노드 배열 처리', () => {
  const pos = layoutEng.layout([], []);
  assert(typeof pos === 'object', '객체가 아님');
});

test('findFreePosition 위치 목록 생성', () => {
  const positions = layoutEng.findFreePosition({}, 4);
  assert(positions.length === 4, `4개 아님: ${positions.length}`);
  assert(positions[0].x >= 0, 'x < 0');
});

// ──────────────────────────────────────────
// 4. AINodeGenerator 통합 테스트
// ──────────────────────────────────────────
console.log('\n📌 AINodeGenerator 통합 (10개)');

const gen = new AINodeGenerator();

async function testAsync(name, fn) {
  try {
    await fn();
    console.log(`  ✅ ${name}`);
    passed++;
  } catch (e) {
    console.log(`  ❌ ${name}: ${e.message}`);
    failed++;
  }
}

async function runIntegrationTests() {
  await testAsync('로그인 폼 생성 전체 흐름', async () => {
    const r = await gen.generate('로그인 폼 만들어줘');
    assert(typeof r.nodes === 'object', 'nodes 없음');
    assert(r.edges.length > 0, 'edges 없음');
    assertEqual(r.intent, 'login', '의도');
  });

  await testAsync('노드에 position 포함', async () => {
    const r = await gen.generate('카운터');
    for (const n of Object.values(r.nodes)) {
      assert(typeof n.position?.x === 'number', `position.x 없음: ${n.id}`);
      assert(typeof n.position?.y === 'number', `position.y 없음: ${n.id}`);
    }
  });

  await testAsync('엣지에 id 부여', async () => {
    const r = await gen.generate('로그인');
    for (const e of r.edges) {
      assert(e.id, '엣지 id 없음');
    }
  });

  await testAsync('nodeCount/edgeCount 정보 포함', async () => {
    const r = await gen.generate('대시보드');
    assert(typeof r.nodeCount === 'number', 'nodeCount 없음');
    assert(typeof r.edgeCount === 'number', 'edgeCount 없음');
    assert(r.nodeCount > 0, 'nodeCount 0');
  });

  await testAsync('offsetX/Y 옵션 적용', async () => {
    const r = await gen.generate('버튼', { offsetX: 300, offsetY: 200 });
    const positions = Object.values(r.nodes).map(n => n.position);
    assert(positions.some(p => p.x >= 300), 'offsetX 미적용');
  });

  await testAsync('todo 생성 label 확인', async () => {
    const r = await gen.generate('할일 목록 만들어');
    assert(r.label.length > 0, 'label 없음');
  });

  await testAsync('register 생성', async () => {
    const r = await gen.generate('회원가입 폼');
    assertEqual(r.intent, 'register', '의도');
    assert(r.nodeCount >= 5, `노드 부족: ${r.nodeCount}`);
  });

  await testAsync('search UI 생성', async () => {
    const r = await gen.generate('검색 기능');
    assertEqual(r.intent, 'search', '의도');
  });

  await testAsync('setLLMEndpoint 설정', async () => {
    const g = new AINodeGenerator();
    g.setLLMEndpoint('http://localhost:11434/api/generate');
    assert(g.llmEndpoint !== null, 'endpoint 없음');
  });

  await testAsync('getSupportedIntents 15개', () => {
    const intents = gen.getSupportedIntents();
    assert(intents.length >= 15, `${intents.length}개`);
    assert(intents[0].intent && intents[0].example, '구조 오류');
  });

  // 최종 결과
  console.log('\n─────────────────────────────────');
  if (failed === 0) {
    console.log(`✅ 전체 통과: ${passed}/${passed + failed}`);
  } else {
    console.log(`결과: ${passed} 통과 / ${failed} 실패`);
  }
  console.log('─────────────────────────────────\n');

  process.exit(failed > 0 ? 1 : 0);
}

runIntegrationTests();

