/* ─── 메인 ──────────── */
#editor-container {
  flex: 1;
  overflow: hidden;
}

/* ─── 하단 상태바 ──── */
#statusbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 12px;
  height: 24px;
  background: var(--bg2);
  border-top: 1px solid var(--border);
  font-size: 11px;
  color: var(--dim);
  flex-shrink: 0;
}

#statusbar .status-item {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ─── 시작 템플릿 모달 ─ */
#template-modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}

.modal-card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  width: 520px;
  max-height: 80vh;
  overflow-y: auto;
}

.modal-card h2 {
  font-size: 16px;
  margin-bottom: 4px;
}

.modal-card p {
  color: var(--dim);
  font-size: 12px;
  margin-bottom: 20px;
}

.template-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.template-item {
  padding: 14px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: border-color .15s, background .15s;
}

.template-item:hover {
  border-color: var(--accent);
  background: rgba(88,166,255,.06);
}

.template-item .t-icon { font-size: 24px; margin-bottom: 6px; }
.template-item .t-title { font-size: 13px; font-weight: 600; margin-bottom: 2px; }
.template-item .t-desc { font-size: 11px; color: var(--dim); }

.modal-skip {
  display: block;
  text-align: center;
  margin-top: 16px;
  font-size: 12px;
  color: var(--dim);
  cursor: pointer;
  text-decoration: underline;
}

