// ─── NodeView ─────────────────────────────────────────────────────
class NodeView {
  constructor(id, def, x, y, editor) {
    this.id = id;
    this.def = { ...def, inputs:[...(def.inputs??[])], outputs:[...(def.outputs??[])], props:{...(def.props??{})} };
    this.x = x; this.y = y;
    this.editor = editor;
    this.width = 190;
    this.el = document.createElement('div');
    this.el.className = 'fw-node';
    this.el.style.cssText = `position:absolute;left:${x}px;top:${y}px;width:${this.width}px;background:#161b22;border:1px solid #30363d;border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.5);user-select:none;`;
    this.el.dataset.nodeId = id;
    this._render();
  }

  _render() {
    const tc = PORT_COLORS[this.def.type] ?? '#8b949e';
    const ins = this.def.inputs.map((p,i) => `
      <div style="display:flex;align-items:center;gap:5px;padding:3px 6px;">
        <div class="fw-port" data-port-idx="${i}" data-is-output="0" data-node="${this.id}"
          style="width:11px;height:11px;border-radius:50%;background:${PORT_COLORS[p.portType]??'#8b949e'};border:2px solid #0d1117;cursor:crosshair;flex-shrink:0;transition:transform .1s;"></div>
        <span style="font-size:11px;color:#8b949e;">${p.name}</span>
      </div>`).join('');

    const outs = this.def.outputs.map((p,i) => `
      <div style="display:flex;align-items:center;justify-content:flex-end;gap:5px;padding:3px 6px;">
        <span style="font-size:11px;color:#8b949e;">${p.name}</span>
        <div class="fw-port" data-port-idx="${i}" data-is-output="1" data-node="${this.id}"
          style="width:11px;height:11px;border-radius:50%;background:${PORT_COLORS[p.portType]??'#8b949e'};border:2px solid #0d1117;cursor:crosshair;flex-shrink:0;transition:transform .1s;"></div>
      </div>`).join('');

    const props = Object.entries(this.def.props).map(([k,v]) => `
      <div style="display:flex;align-items:center;gap:4px;padding:2px 8px;">
        <span style="font-size:10px;color:#8b949e;min-width:48px;">${k}</span>
        <input class="fw-prop" data-key="${k}" value="${String(v??'').replace(/"/g,'&quot;')}"
          style="flex:1;background:#0d1117;border:1px solid #30363d;color:#e6edf3;padding:2px 5px;border-radius:3px;font-size:11px;min-width:0;"/>
      </div>`).join('');

    this.el.innerHTML = `
      <div class="fw-node-bar" style="padding:7px 10px;border-bottom:1px solid #30363d;background:${tc}18;border-radius:8px 8px 0 0;cursor:move;display:flex;align-items:center;justify-content:space-between;">
        <span style="font-size:12px;font-weight:700;color:${tc};">${this.def.label}</span>
        <div style="display:flex;gap:3px;align-items:center;">
          <span style="font-size:9px;color:#8b949e;padding:1px 5px;background:#21262d;border-radius:3px;">${this.def.type}</span>
          <button class="fw-del" style="background:none;border:none;color:#8b949e;cursor:pointer;font-size:12px;padding:0 2px;line-height:1;">✕</button>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:0;padding:4px 0;">
        <div>${ins}</div><div>${outs}</div>
      </div>
      ${props ? `<div style="border-top:1px solid #21262d;padding:4px 0;">${props}</div>` : ''}
    `;
    this._bindEvents();
  }

  _bindEvents() {
    this.el.querySelector('.fw-node-bar').addEventListener('mousedown', e => {
      if (e.target.classList.contains('fw-del')) return;
      this.editor.startNodeDrag(this.id, e); e.preventDefault();
    });
    this.el.querySelector('.fw-del').addEventListener('click', () => this.editor._removeNode(this.id));
    this.el.querySelectorAll('.fw-port').forEach(p => {
      p.addEventListener('mousedown', e => {
        e.stopPropagation();
        this.editor.startWireDrag(this.id, +p.dataset.portIdx, p.dataset.isOutput==='1'); e.preventDefault();
      });
      p.addEventListener('mouseenter', () => p.style.transform = 'scale(1.5)');
      p.addEventListener('mouseleave', () => p.style.transform = '');
    });
    this.el.querySelectorAll('.fw-prop').forEach(inp => {
      inp.addEventListener('change', e => { this.def.props[e.target.dataset.key] = e.target.value; });
      inp.addEventListener('mousedown', e => e.stopPropagation());
    });

