// ─── AI 노드 생성기 (인라인 번들) ─────────────────────────────

let _aiIdCtr = 1;
const aiUid = () => `ai-${_aiIdCtr++}`;

const AI_NODE = {
  button:    (label='버튼', variant='primary') => ({ id:aiUid(), type:'component', subtype:'button', label:`버튼[${label}]`, inputs:[{name:'props',portType:'data'},{name:'onClick',portType:'logic'}], outputs:[{name:'element',portType:'component'}], props:{label,variant} }),
  text:      (content='텍스트', tag='p')       => ({ id:aiUid(), type:'component', subtype:'text',   label:`텍스트[${content.slice(0,8)}]`, inputs:[{name:'content',portType:'data'}], outputs:[{name:'element',portType:'component'}], props:{content,tag} }),
  input:     (placeholder='입력', type='text') => ({ id:aiUid(), type:'component', subtype:'input',  label:`입력[${placeholder}]`, inputs:[{name:'value',portType:'data'},{name:'onChange',portType:'logic'}], outputs:[{name:'element',portType:'component'},{name:'value',portType:'data'}], props:{placeholder,type} }),
  card:      (title='카드')                    => ({ id:aiUid(), type:'component', subtype:'card',   label:`카드[${title}]`, inputs:[{name:'title',portType:'data'},{name:'children',portType:'component'}], outputs:[{name:'element',portType:'component'}], props:{title} }),
  container: (direction='column')             => ({ id:aiUid(), type:'component', subtype:'container', label:'컨테이너', inputs:[{name:'children',portType:'component'}], outputs:[{name:'element',portType:'component'}], props:{direction,gap:'12px'} }),
  state:     (name='value', initial='0')      => ({ id:aiUid(), type:'data',      subtype:'state',  label:`상태[${name}]`, inputs:[{name:'set',portType:'data'}], outputs:[{name:'value',portType:'data'}], props:{name,initial} }),
  constant:  (value='', valueType='string')   => ({ id:aiUid(), type:'data',      subtype:'const',  label:'상수', inputs:[], outputs:[{name:'value',portType:'data'}], props:{value,valueType} }),
  array:     (items='[]')                     => ({ id:aiUid(), type:'data',      subtype:'array',  label:'배열', inputs:[], outputs:[{name:'items',portType:'data'}], props:{items} }),
  handler:   (name='handleClick')             => ({ id:aiUid(), type:'logic',     subtype:'handler',label:`핸들러[${name}]`, inputs:[{name:'action',portType:'logic'}], outputs:[{name:'handler',portType:'logic'}], props:{name} }),
};

const AI_PATTERNS = [
  [/로그인|login|sign.?in/,   'login'],
  [/회원가입|register|sign.?up/, 'register'],
  [/카운터|counter/,            'counter'],
  [/검색|search/,               'search'],
  [/(할일|todo|task)/,          'todo'],
  [/(프로필|profile).*(카드|card)?/, 'profile-card'],
  [/(댓글|comment).*(폼|form)?/, 'comment-form'],
  [/(결제|payment|checkout)/,   'checkout'],
  [/(설정|setting)/,            'settings'],
  [/(대시보드|dashboard)/,      'dashboard'],
  [/(모달|modal|팝업|popup)/,   'modal'],
  [/네비게이션|navbar/,          'navbar'],
  [/(입력|input).*(폼|form)/,   'input-form'],
  [/버튼/,                      'single-button'],
  [/카드/,                      'single-card'],
];

const AI_TEMPLATES = {
  login: () => {
    const email=AI_NODE.input('이메일','email'), pw=AI_NODE.input('비밀번호','password');
    const btn=AI_NODE.button('로그인','primary'), h=AI_NODE.handler('handleLogin'), card=AI_NODE.card('로그인');
    return { nodes:[card,email,pw,btn,h], edges:[
      {from:email.id,fromPort:0,to:card.id,toPort:0},{from:pw.id,fromPort:0,to:card.id,toPort:0},
      {from:btn.id,fromPort:0,to:card.id,toPort:0},{from:h.id,fromPort:0,to:btn.id,toPort:1}], label:'로그인 폼' };
  },
  register: () => {
    const name=AI_NODE.input('이름'), email=AI_NODE.input('이메일','email');
    const pw=AI_NODE.input('비밀번호','password'), pw2=AI_NODE.input('비밀번호 확인','password');
    const btn=AI_NODE.button('회원가입','primary'), h=AI_NODE.handler('handleRegister'), card=AI_NODE.card('회원가입');
    return { nodes:[card,name,email,pw,pw2,btn,h], edges:[
      {from:name.id,fromPort:0,to:card.id,toPort:0},{from:email.id,fromPort:0,to:card.id,toPort:0},
      {from:pw.id,fromPort:0,to:card.id,toPort:0},{from:pw2.id,fromPort:0,to:card.id,toPort:0},
      {from:btn.id,fromPort:0,to:card.id,toPort:0},{from:h.id,fromPort:0,to:btn.id,toPort:1}], label:'회원가입 폼' };
  },
  counter: () => {
    const st=AI_NODE.state('count','0'), disp=AI_NODE.text('0','h2');
    const inc=AI_NODE.button('+1','primary'), dec=AI_NODE.button('-1','secondary'), reset=AI_NODE.button('초기화','ghost');
    const incH=AI_NODE.handler('handleInc'), decH=AI_NODE.handler('handleDec'), row=AI_NODE.container('row');
    return { nodes:[st,disp,inc,dec,reset,incH,decH,row], edges:[
      {from:st.id,fromPort:0,to:disp.id,toPort:0},{from:incH.id,fromPort:0,to:inc.id,toPort:1},
      {from:decH.id,fromPort:0,to:dec.id,toPort:1},{from:inc.id,fromPort:0,to:row.id,toPort:0},
      {from:dec.id,fromPort:0,to:row.id,toPort:0},{from:reset.id,fromPort:0,to:row.id,toPort:0}], label:'카운터 앱' };
  },
  search: () => {
    const qs=AI_NODE.state('query','""'), inp=AI_NODE.input('검색어...','text');
