use wasm_bindgen::prelude::*;
use serde::{Serialize, Deserialize};

// 패닉 메시지를 브라우저 콘솔에 출력
fn init_panic_hook() {
    console_error_panic_hook::set_once();
}

// JS에 전달할 평가 결과 구조체
#[derive(Serialize, Deserialize, Debug)]
pub struct EvalResult {
    pub success: bool,
    pub output: String,
    pub error: Option<String>,
    pub ast_json: Option<String>,
}

/// FV-Lang 코드 평가 (REPL 핵심)
#[wasm_bindgen]
pub fn eval_fv(code: &str) -> JsValue {
    init_panic_hook();

    let result = run_fv_code(code);
    serde_wasm_bindgen::to_value(&result).unwrap_or(JsValue::NULL)
}

/// AST를 JSON으로 직렬화해서 반환 (시각화용)
#[wasm_bindgen]
pub fn parse_to_ast(code: &str) -> String {
    init_panic_hook();

    let lexer = match fv_lang::Lexer::new(code) {
        Ok(l) => l,
        Err(e) => return format!("{{\"error\": \"Lexer 오류: {}\"}}", e),
    };
    match lexer.tokenize() {
        Ok(tokens) => {
            let parser = match fv_lang::Parser::new(tokens) {
                Ok(p) => p,
