/* ─── 메인 분할 레이아웃 ─ */
#main-split {
  flex: 1;
  display: flex;
  overflow: hidden;
}

#editor-container {
  flex: 1;
  overflow: hidden;
  min-width: 0;
  transition: flex .2s;
}

/* ─── 미리보기 패널 ──── */
#preview-panel {
  width: 360px;
  min-width: 300px;
  max-width: 560px;
  background: var(--bg2);
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  display: none;
}
#preview-panel.open { display: flex; }

#preview-panel .pv-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}

#preview-panel .pv-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--green);
  flex: 1;
}

.pv-tab {
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 11px;
  cursor: pointer;
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--dim);
  transition: all .1s;
}
.pv-tab.active {
  background: rgba(63,185,80,.15);
  border-color: var(--green);
  color: var(--green);
}

.pv-close {
  background: none;
  border: none;
  color: var(--dim);
  cursor: pointer;
  font-size: 13px;
  padding: 0 4px;
}

#preview-frame {
  flex: 1;
  border: none;
  background: #fff;
  display: block;
}

#code-view {
  flex: 1;
  overflow-y: auto;
  padding: 10px;
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.6;
  color: #e6edf3;
  white-space: pre;
  display: none;
}
#code-view.active { display: block; }
#preview-frame.active { display: block; }

