  transition: background .15s;
}
.btn-preview:hover { background: rgba(63,185,80,.25); }
.btn-preview.running {
  background: rgba(63,185,80,.3);
  animation: pulse .8s infinite;
}
@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.6} }

