function generateHTML(compNodes, stateNodes, nodesArr, wiresArr) {
  // 위상 정렬: 컨테이너/카드가 자식 먼저 삽입되는 순서
  const parts = [];

  // 카드/컨테이너 감지
  const containers = compNodes.filter(n => n.subtype === 'card' || n.subtype === 'container');
  const inContainer = new Set();

  // 컨테이너에 연결된 자식 수집
  const childrenOf = {};
  for (const c of containers) {
    childrenOf[c.id] = [];
  }
  for (const w of wiresArr) {
    const srcDef = nodesArr.find(n => n.id === (w.fn ?? w.from));
    const dstDef = nodesArr.find(n => n.id === (w.tn ?? w.to));
    if (srcDef && dstDef && childrenOf[dstDef.id] !== undefined) {
      childrenOf[dstDef.id].push(srcDef);
      inContainer.add(srcDef.id);
    }
  }

  function nodeToHTML(n) {
    const p = n.props ?? {};
    const id = n.id ?? '';
    if (n.subtype === 'button') {
      const cls = p.variant ?? 'primary';
      const stateTarget = stateNodes[0];
      const bindAttr = stateTarget ? ` data-bind="${stateTarget.props?.name}"` : '';
      return `<button class="${cls}" data-fw-id="${id}">${p.label ?? '버튼'}</button>`;
    }
    if (n.subtype === 'text') {
      const tag = p.tag ?? 'p';
      const stateName = stateNodes[0]?.props?.name;
      const hasState = stateNodes.some(s => {
        return wiresArr.some(w => (w.fn ?? w.from) === s.id && (w.tn ?? w.to) === n.id);
      });
      const content = hasState && stateName
        ? `<span data-bind="${stateName}">${stateNodes[0]?.props?.initial ?? '0'}</span>`
        : (p.content ?? '텍스트');
      return `<${tag}>${content}</${tag}>`;
    }
    if (n.subtype === 'input') {
      return `<input type="${p.type ?? 'text'}" placeholder="${p.placeholder ?? ''}" />`;
    }
    if (n.subtype === 'card') {
      const children = (childrenOf[id] ?? []).map(nodeToHTML).join('\n      ');
      return `<div class="card">\n      <div class="card-title">${p.title ?? '카드'}</div>\n      ${children}\n    </div>`;
    }
    if (n.subtype === 'container') {
      const dir = p.direction === 'row' ? 'row' : 'col';
      const children = (childrenOf[id] ?? []).map(nodeToHTML).join('\n      ');
      return `<div class="container-${dir}">\n      ${children}\n    </div>`;
    }
    return '';
  }

  // 최상위 노드만 렌더링 (컨테이너에 속하지 않은 것)
  for (const n of compNodes) {
    if (!inContainer.has(n.id)) {
      const html = nodeToHTML(n);
      if (html) parts.push('    ' + html);
    }
  }

  // 노드가 없으면 플레이스홀더
  if (parts.length === 0) {
    return '<div class="fw-app"><p style="color:#94a3b8;text-align:center">노드를 추가하고 ▶ 실행을 누르세요</p></div>';
  }

  return `<div class="fw-app">\n${parts.join('\n')}\n  </div>`;
}

