test('여러 상태 모두 포함', () => {
  const nodes = mockNodes([
    { id:'s1', type:'data', subtype:'state', props:{name:'a',initial:'1'} },
    { id:'s2', type:'data', subtype:'state', props:{name:'b',initial:'2'} },
  ]);
  const r = browserCompileTest(nodes, new Map());
  assert(r.js.includes('var a'), `a 없음`);
  assert(r.js.includes('var b'), `b 없음`);
});

// ──────────────────────────────────────────
// 4. 통합 케이스
// ──────────────────────────────────────────
console.log('\n📌 통합 케이스 (4개)');

test('카운터 전체 컴파일', () => {
  const nodes = mockNodes([
    { id:'s1', type:'data',      subtype:'state',   props:{name:'count',initial:'0'} },
    { id:'t1', type:'component', subtype:'text',    props:{content:'0',tag:'h2'} },
    { id:'b1', type:'component', subtype:'button',  props:{label:'+1',variant:'primary'} },
    { id:'b2', type:'component', subtype:'button',  props:{label:'-1',variant:'secondary'} },
  ]);
  const wires = mockWires([{ from:'s1', to:'t1', fromPort:0, toPort:0 }]);
  const r = browserCompileTest(nodes, wires);
  assert(r.freelang.includes('count: 0'), 'state 없음');
  assert(r.html.includes('<button'), 'button 없음');
  assert(r.html.includes('data-bind="count"'), 'data-bind 없음');
  assert(r.js.includes('var count'), 'JS 없음');
});

test('로그인 폼 전체 컴파일', () => {
  const nodes = mockNodes([
    { id:'i1', type:'component', subtype:'input',  props:{placeholder:'이메일',type:'email'} },
    { id:'i2', type:'component', subtype:'input',  props:{placeholder:'비밀번호',type:'password'} },
    { id:'b1', type:'component', subtype:'button', props:{label:'로그인',variant:'primary'} },
    { id:'c1', type:'component', subtype:'card',   props:{title:'로그인'} },
  ]);
  const wires = mockWires([
    { from:'i1', to:'c1' }, { from:'i2', to:'c1' }, { from:'b1', to:'c1' }
  ]);
  const r = browserCompileTest(nodes, wires);
  assert(r.html.includes('이메일'), '이메일 없음');
  assert(r.html.includes('로그인'), '로그인 없음');
  assert(r.html.includes('class="card"'), 'card 없음');
});

test('빈 그래프 플레이스홀더', () => {
  const r = browserCompileTest(new Map(), new Map());
  assert(typeof r.html === 'string', 'html 없음');
  assert(typeof r.css === 'string',  'css 없음');
  assert(typeof r.freelang === 'string', 'freelang 없음');
});

test('반환 객체 구조 검증', () => {
  const nodes = mockNodes([{ id:'b1', type:'component', subtype:'button', props:{label:'확인'} }]);
  const r = browserCompileTest(nodes, new Map());
  assert('html' in r, 'html 없음');
  assert('css' in r, 'css 없음');
  assert('js' in r, 'js 없음');
  assert('freelang' in r, 'freelang 없음');
});

