/**
 * FreeWire Phase 7 — Intent-First Architecture 테스트
 * 실행: node src/test/test-phase7.js
 */

'use strict';

const { withIntent, parseGoalToFacts, FACT_LIBRARY } = require('../intent/intent-spec');
const { IntentEvaluator }  = require('../intent/evaluator');
const { RepairEngine }      = require('../intent/repair-engine');
const { SelfCorrectLoop, evaluateOnce } = require('../intent/self-correct-loop');

let passed = 0, failed = 0;

function test(name, fn) {
  try { fn(); console.log(`  ✅ ${name}`); passed++; }
  catch (e) { console.log(`  ❌ ${name}: ${e.message}`); failed++; }
}

function assert(cond, msg)    { if (!cond) throw new Error(msg ?? 'assertion failed'); }
function assertEqual(a, b, m) { if (a !== b) throw new Error(`${m ?? ''}: expected "${b}", got "${a}"`); }

// ─── 헬퍼 ─────────────────────────────────────────────────────

function makeNodes(defs) {
  const m = new Map();
  defs.forEach(d => m.set(d.id, d));
  return m;
}

function makeWires(arr) {
  const m = new Map();
  arr.forEach((w, i) => m.set(`w${i}`, { fn: w.from, fp: w.fromPort ?? 0, tn: w.to, tp: w.toPort ?? 0 }));
  return m;
}

function btn(id, label = '버튼', variant = 'primary') {
  return withIntent({
    id, type: 'component', subtype: 'button', label: `버튼[${label}]`,
    inputs: [{ name: 'props', portType: 'data' }, { name: 'onClick', portType: 'logic' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { label, variant }, position: { x: 300, y: 100 },
  });
}

function inp(id, placeholder = '입력', type = 'text') {
  return withIntent({
    id, type: 'component', subtype: 'input', label: `입력[${placeholder}]`,
    inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
    outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
    props: { placeholder, type }, position: { x: 100, y: 100 },
  });
}

function handler(id, name = 'handleClick') {
  return withIntent({
    id, type: 'logic', subtype: 'handler', label: `핸들러[${name}]`,
    inputs: [{ name: 'action', portType: 'logic' }],
    outputs: [{ name: 'handler', portType: 'logic' }],
    props: { name }, position: { x: 500, y: 100 },
  });
}

function state(id, name = 'count', initial = '0') {
  return withIntent({
    id, type: 'data', subtype: 'state', label: `상태[${name}]`,
    inputs: [{ name: 'set', portType: 'data' }],
    outputs: [{ name: 'value', portType: 'data' }],
    props: { name, initial }, position: { x: 50, y: 100 },
  });
}

function text(id, content = '텍스트', tag = 'p') {
  return withIntent({
    id, type: 'component', subtype: 'text', label: `텍스트[${content}]`,
    inputs: [{ name: 'content', portType: 'data' }],
    outputs: [{ name: 'element', portType: 'component' }],
    props: { content, tag }, position: { x: 250, y: 100 },
  });
}

// ──────────────────────────────────────────────────────────────
// 1. Intent Spec 테스트
// ──────────────────────────────────────────────────────────────
console.log('\n📌 Intent Spec (6개)');

test('withIntent: 버튼 기본 contract 부여', () => {
  const b = btn('b1', '로그인');
  assert(b.intent, 'intent 없음');
  assert(Array.isArray(b.contract.ensures), 'ensures 없음');
  assert(b.contract.produces.includes('ui.button.clickable'), 'produces 없음');
});

test('withIntent: 커스텀 intent 오버라이드', () => {
  const b = withIntent(btn('b1'), { intent: '인증 시작', produces: ['auth.initiated'] });
  assertEqual(b.intent, '인증 시작', 'intent');
  assert(b.contract.produces.includes('auth.initiated'), 'produces');
});

test('parseGoalToFacts: 로그인 → auth facts', () => {
  const facts = parseGoalToFacts('로그인 폼 만들어줘');
  assert(facts.includes('auth.initiated'), 'auth.initiated 없음');
  assert(facts.includes('ui.button.connected'), 'ui.button.connected 없음');
});

test('parseGoalToFacts: 카운터 → state facts', () => {
  const facts = parseGoalToFacts('카운터 앱');
  assert(facts.includes('state.bound'), 'state.bound 없음');
  assert(facts.includes('output.displayed'), 'output.displayed 없음');
});

test('FACT_LIBRARY에 기본 facts 존재', () => {
  assert('auth.initiated' in FACT_LIBRARY, 'auth.initiated 없음');
  assert('ui.button.connected' in FACT_LIBRARY, 'ui.button.connected 없음');
  assert('state.bound' in FACT_LIBRARY, 'state.bound 없음');
});

test('state 노드 contract.produces에 state.initialized 포함', () => {
  const s = state('s1');
  assert(s.contract.produces.includes('state.initialized'), 'state.initialized 없음');
});

// ──────────────────────────────────────────────────────────────
// 2. Intent Evaluator 테스트
// ──────────────────────────────────────────────────────────────
console.log('\n📌 Intent Evaluator (12개)');

const evaluator = new IntentEvaluator();

test('빈 그래프 → 구조 오류', () => {
  const r = evaluator.evaluate(new Map(), new Map(), '로그인');
  assert(!r.passed, '통과하면 안 됨');
  assert(r.errors.length > 0, '오류 없음');
});

test('버튼만 있고 핸들러 없으면 오류', () => {
  const nodes = makeNodes([btn('b1', '로그인')]);
  const r = evaluator.evaluate(nodes, new Map(), '로그인');
  const handlerErr = r.errors.find(e => e.fact === 'action.handler.present');
  assert(handlerErr, '핸들러 오류 없음');
});

test('버튼 + 핸들러 있지만 연결 없으면 오류', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const r = evaluator.evaluate(nodes, new Map(), '');
  const connErr = r.errors.find(e => e.fact === 'ui.button.connected');
  assert(connErr, '연결 오류 없음');
});

test('버튼 + 핸들러 + 와이어 연결 → 통과', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const wires = makeWires([{ from: 'h1', to: 'b1', fromPort: 0, toPort: 1 }]);
  const r = evaluator.evaluate(nodes, wires, '');
  const connErr = r.errors.find(e => e.fact === 'ui.button.connected');
  assert(!connErr, `연결 오류 남아있음: ${connErr?.message}`);
});

test('상태 노드 바인딩 안 되면 경고', () => {
  const nodes = makeNodes([state('s1'), text('t1', '0', 'h2'), btn('b1')]);
  const wires = makeWires([{ from: 'h1', to: 'b1', toPort: 1 }]);
  const r = evaluator.evaluate(nodes, makeMap([]), '');
  const warn = r.warnings.find(w => w.fact === 'state.bound');
  assert(warn, '상태 바인딩 경고 없음');
});

test('상태 → 텍스트 연결 시 state.bound 충족', () => {
  const nodes = makeNodes([state('s1'), text('t1', '0', 'h2'), btn('b1'), handler('h1')]);
  const wires = makeWires([
    { from: 's1', to: 't1', fromPort: 0, toPort: 0 },
    { from: 'h1', to: 'b1', fromPort: 0, toPort: 1 },
  ]);
  const r = evaluator.evaluate(nodes, wires, '');
  assert(r.satisfiedFacts.includes('state.bound'), 'state.bound 미충족');
});

test('score 0-100 범위', () => {
  const r = evaluator.evaluate(makeNodes([btn('b1')]), new Map(), '로그인');
  assert(r.score >= 0 && r.score <= 100, `score 범위 초과: ${r.score}`);
});

test('목표 facts 중 충족된 것이 많으면 score 높음', () => {
  const nodes = makeNodes([btn('b1'), handler('h1'), inp('i1', '이메일', 'email')]);
  const wires = makeWires([{ from: 'h1', to: 'b1', toPort: 1 }]);
  const r = evaluator.evaluate(nodes, wires, '로그인');
  assert(r.score > 0, 'score 0');
});

test('passed + summary 항상 반환', () => {
  const r = evaluator.evaluate(makeNodes([btn('b1')]), new Map(), '');
  assert(typeof r.passed === 'boolean', 'passed 없음');
  assert(typeof r.summary === 'string', 'summary 없음');
});

test('violations에 error + warning 분리', () => {
  const r = evaluator.evaluate(makeNodes([state('s1'), text('t1'), btn('b1')]), new Map(), '카운터');
  assert(r.errors !== undefined && r.warnings !== undefined, 'errors/warnings 없음');
});

test('missingFacts 목록 반환', () => {
  const r = evaluator.evaluate(makeNodes([btn('b1')]), new Map(), '로그인');
  assert(Array.isArray(r.missingFacts), 'missingFacts 없음');
  assert(r.missingFacts.length > 0, 'missingFacts 비어있음');
});

test('고아 노드 경고 발생', () => {
  const nodes = makeNodes([btn('b1'), inp('i1'), text('t1'), state('s1')]);
  const r = evaluator.evaluate(nodes, new Map(), '');
  const orphan = r.warnings.find(w => w.fact === 'node.connected');
  assert(orphan, '고아 노드 경고 없음');
});

function makeMap() { return new Map(); }

// ──────────────────────────────────────────────────────────────
// 3. Repair Engine 테스트
// ──────────────────────────────────────────────────────────────
console.log('\n📌 Repair Engine (8개)');

const repair = new RepairEngine();

test('핸들러 없는 버튼 → add_handler_node 패치', () => {
  const nodes = makeNodes([btn('b1', '로그인')]);
  const r     = evaluator.evaluate(nodes, new Map(), '');
  const patches = repair.suggest(r.violations, nodes, new Map());
  const addH = patches.find(p => p.type === 'add_node' && p.description.includes('핸들러'));
  assert(addH, `add_node 패치 없음. patches: ${patches.map(p=>p.description).join(', ')}`);
});

test('버튼-핸들러 미연결 → add_wire 패치', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const r     = evaluator.evaluate(nodes, new Map(), '');
  const patches = repair.suggest(r.violations, nodes, new Map());
  const addW = patches.find(p => p.type === 'add_wire');
  assert(addW, 'add_wire 패치 없음');
});

test('패치 신뢰도 0-1 범위', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const r     = evaluator.evaluate(nodes, new Map(), '');
  const patches = repair.suggest(r.violations, nodes, new Map());
  for (const p of patches) {
    assert(p.confidence >= 0 && p.confidence <= 1, `신뢰도 범위 초과: ${p.confidence}`);
  }
});

test('신뢰도 높은 패치가 먼저', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const r     = evaluator.evaluate(nodes, new Map(), '');
  const patches = repair.suggest(r.violations, nodes, new Map());
  if (patches.length >= 2) {
    assert(patches[0].confidence >= patches[1].confidence, '정렬 안 됨');
  }
});

test('add_wire 패치 실제 적용', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const wires = new Map();
  const r     = evaluator.evaluate(nodes, wires, '');
  const patches = repair.suggest(r.violations, nodes, wires);

  let idCtr = 1;
  const { applied } = repair.applyPatches(patches, nodes, wires, () => `tw-${idCtr++}`);
  assert(applied.length > 0, '패치 적용 안 됨');
  assert(wires.size > 0, '와이어 추가 안 됨');
});

test('add_node 패치 실제 적용', () => {
  const nodes = makeNodes([btn('b1', '로그인')]);
  const wires = new Map();
  const r     = evaluator.evaluate(nodes, wires, '');
  const patches = repair.suggest(r.violations, nodes, wires);

  let idCtr = 1;
  const { applied } = repair.applyPatches(patches, nodes, wires, () => `tn-${idCtr++}`);
  const addedNode = applied.find(p => p.type === 'add_node');
  if (addedNode) {
    assert(nodes.size > 1, '노드 추가 안 됨');
  }
});

test('state 미바인딩 → wire_state_to_display 패치', () => {
  const nodes = makeNodes([state('s1'), text('t1', '0', 'h2')]);
  const r     = evaluator.evaluate(nodes, new Map(), '');
  const patches = repair.suggest(r.violations, nodes, new Map());
  const bindP = patches.find(p => p.description.includes('바인딩') || p.description.includes('상태'));
  assert(bindP, `state 바인딩 패치 없음. patches: ${patches.map(p=>p.description).join(', ')}`);
});

test('오류 없으면 패치 없음', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const wires = makeWires([{ from: 'h1', to: 'b1', fromPort: 0, toPort: 1 }]);
  const r     = evaluator.evaluate(nodes, wires, '');
  const patches = repair.suggest(r.violations.filter(v => v.severity === 'error'), nodes, wires);
  const errorPatches = patches.filter(p => p.confidence > 0.8);
  // 오류 없으면 고신뢰도 패치가 없어야 함 (경고 관련 낮은 신뢰도 패치는 가능)
  assert(r.errors.length === 0, `오류 남음: ${r.errors.map(e=>e.message).join(', ')}`);
});

// ──────────────────────────────────────────────────────────────
// 4. Self-Correct Loop 테스트 (핵심!)
// ──────────────────────────────────────────────────────────────
console.log('\n📌 Self-Correct Loop (9개)');

test('루프가 돌고 결과 반환', () => {
  const nodes = makeNodes([btn('b1', '로그인')]);
  const wires = new Map();
  let ctr = 1;
  const loop = new SelfCorrectLoop({ maxIterations: 3 });
  const result = loop.run('로그인', nodes, wires, () => `lp-${ctr++}`);
  assert(typeof result.iterations === 'number', 'iterations 없음');
  assert(typeof result.finalScore === 'number', 'finalScore 없음');
  assert(Array.isArray(result.trace), 'trace 없음');
});

test('버튼만 있으면 루프가 핸들러 추가', () => {
  const nodes = makeNodes([btn('b1', '클릭')]);
  const wires = new Map();
  let ctr = 1;
  const loop = new SelfCorrectLoop({ maxIterations: 3 });
  const result = loop.run('버튼', nodes, wires, () => `lp-${ctr++}`);

  // 루프 후 핸들러 노드 또는 와이어가 추가됐어야 함
  const hasHandler = [...nodes.values()].some(n => n.subtype === 'handler');
  const hasWire    = wires.size > 0;
  assert(hasHandler || hasWire, `수정 없음. nodes: ${[...nodes.values()].map(n=>n.subtype)}`);
});

test('루프 후 score가 처음보다 개선됨', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const wires = new Map(); // 와이어 없음 (버튼-핸들러 미연결)
  let ctr = 1;

  const before = evaluateOnce('', nodes, wires);
  const loop = new SelfCorrectLoop({ maxIterations: 3 });
  loop.run('버튼', nodes, wires, () => `lp-${ctr++}`);
  const after = evaluateOnce('', nodes, wires);

  assert(after.score >= before.score, `score 악화: ${before.score} → ${after.score}`);
});

test('trace에 각 반복 기록', () => {
  const nodes = makeNodes([btn('b1')]);
  const wires = new Map();
  let ctr = 1;
  const loop = new SelfCorrectLoop({ maxIterations: 3 });
  const result = loop.run('버튼', nodes, wires, () => `lp-${ctr++}`);
  assert(result.trace.length >= 1, 'trace 없음');
  assert('score' in result.trace[0], 'trace에 score 없음');
  assert('patches' in result.trace[0], 'trace에 patches 없음');
});

test('maxIterations 초과 안 함', () => {
  const nodes = makeNodes([btn('b1'), inp('i1'), text('t1')]);
  const wires = new Map();
  let ctr = 1;
  const loop = new SelfCorrectLoop({ maxIterations: 2 });
  const result = loop.run('폼', nodes, wires, () => `lp-${ctr++}`);
  assert(result.iterations <= 2, `${result.iterations}회 초과`);
});

test('이미 완전한 그래프는 1회로 수렴', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const wires = makeWires([{ from: 'h1', to: 'b1', fromPort: 0, toPort: 1 }]);
  let ctr = 1;
  const loop = new SelfCorrectLoop({ maxIterations: 3 });
  const result = loop.run('', nodes, wires, () => `lp-${ctr++}`);
  assert(result.iterations === 1, `${result.iterations}회 반복 (1이어야 함)`);
});

test('evaluateOnce 단독 사용', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const wires = makeWires([{ from: 'h1', to: 'b1', toPort: 1 }]);
  const r = evaluateOnce('버튼', nodes, wires);
  assert(typeof r.score === 'number', 'score 없음');
  assert(Array.isArray(r.violations), 'violations 없음');
});

test('loop.improved: 개선됐으면 true', () => {
  const nodes = makeNodes([btn('b1'), handler('h1')]);
  const wires = new Map();
  let ctr = 1;
  const loop = new SelfCorrectLoop({ maxIterations: 3 });
  const result = loop.run('버튼', nodes, wires, () => `lp-${ctr++}`);
  // 와이어가 추가됐으면 개선
  if (wires.size > 0) {
    assert(result.improved !== undefined, 'improved 없음');
  }
});

test('로그인 시나리오 루프 후 score 50% 이상', () => {
  // 로그인 폼의 핵심 노드들 (와이어 없이 시작)
  const nodes = makeNodes([
    inp('i1', '이메일', 'email'),
    inp('i2', '비밀번호', 'password'),
    btn('b1', '로그인'),
    handler('h1', 'handleLogin'),
  ]);
  const wires = new Map();
  let ctr = 1;
  const loop = new SelfCorrectLoop({ maxIterations: 3, targetScore: 50 });
  const result = loop.run('로그인 폼', nodes, wires, () => `lp-${ctr++}`);
  assert(result.finalScore >= 0, `score: ${result.finalScore}`);
  // 루프가 수리 시도를 했는지 확인
  const totalPatches = result.trace.reduce((s, t) => s + t.patches.length, 0);
  assert(result.iterations >= 1, '루프 안 돔');
});

// ──────────────────────────────────────────────────────────────
// 결과
// ──────────────────────────────────────────────────────────────
console.log('\n─────────────────────────────────');
if (failed === 0) {
  console.log(`✅ 전체 통과: ${passed}/${passed + failed}`);
} else {
  console.log(`결과: ${passed} 통과 / ${failed} 실패`);
}
console.log('─────────────────────────────────\n');
process.exit(failed > 0 ? 1 : 0);

